<?php declare( strict_types=1 ); namespace Inc\Services\Exam; use Inc\Repositories\WPDBRepositories\ExamGuestSessionRepository; use Inc\Repositories\WPDBRepositories\ExamGuestApplicationRepository; class ExamGuestService { private ExamGuestSessionRepository $sessionRepo; private ExamGuestApplicationRepository $appRepo; private const SESSION_DURATION = 86400; public function __construct( ?ExamGuestSessionRepository $sessionRepo = null, ?ExamGuestApplicationRepository $appRepo = null ) { $this->sessionRepo = $sessionRepo ?? new ExamGuestSessionRepository(); $this->appRepo = $appRepo ?? new ExamGuestApplicationRepository(); } public function issueGuestSession( string $scope, int $sourceId, ?int $participationId = null ): string { $cookieHash = bin2hex( random_bytes( 32 ) ); $now = current_time( 'mysql', true ); $expiresAt = gmdate( 'Y-m-d H:i:s', time() + self::SESSION_DURATION ); $this->sessionRepo->insert( [ 'cookie_hash' => $cookieHash, 'scope' => $scope, 'source_id' => $sourceId, 'participation_id' => $participationId, 'issued_at' => $now, 'expires_at' => $expiresAt, ] ); return $cookieHash; } public function verifyGuestSession( string $cookieHash ): bool { $session = $this->sessionRepo->findByCookieHash( $cookieHash ); if ( ! $session ) { return false; } if ( current_time( 'mysql', true ) > $session->expiresAt ) { return false; } return true; } public function createGuestApplication( int $eventId, int $sessionId, int $sourceId, string $identityHash, string $requestKey ): int { return $this->appRepo->insert( [ 'event_id' => $eventId, 'session_id' => $sessionId, 'source_id' => $sourceId, 'identity_hash' => $identityHash, 'active_slot' => 1, 'state' => 'hold', 'is_held' => 1, 'request_key' => $requestKey, 'hold_expires_at' => gmdate( 'Y-m-d H:i:s', time() + 3600 ), 'created_at' => current_time( 'mysql', true ), ] ); } public function confirmGuestApplication( int $applicationId ): bool { return $this->appRepo->update( $applicationId, [ 'state' => 'confirmed', 'is_held' => 0, 'hold_expires_at' => null, ] ); } public function rejectGuestApplication( int $applicationId ): bool { return $this->appRepo->update( $applicationId, [ 'state' => 'rejected', 'active_slot' => null, ] ); } }
